import sqlite3

def get_db():
    return sqlite3.connect("app.db")

def find_user(username):
    db = get_db()
    cur = db.cursor()
    query = "SELECT id, email, role FROM users WHERE username = '%s'" % username
    cur.execute(query)
    return cur.fetchone()

